sys_script_client.script:
function onSubmit() {
    // 1. Só aplicamos a trava de lotação se for a criação de um registro NOVO
    if (!g_form.isNewRecord()) {
        return true; // Se for apenas uma edição, permite salvar normalmente
    }

    // Pega o sys_id da Base que está preenchida no formulário
    var baseId = g_form.getValue('base');
    if (!baseId) {
        return true; 
    }

    // 2. Chama o nosso Script Include (BaseVagasUtil) no servidor para checar as vagas
    var ga = new GlideAjax('global.BaseVagasUtil'); 
    ga.addParam('sysparm_name', 'getBasesComVaga');

    // O getXMLWait() trava a tela rapidinho até o servidor responder
    ga.getXMLWait(); 
    var basesComVaga = ga.getAnswer();

    // Segurança: se não retornou nada, deixa passar (ou barra, dependendo da sua preferência)
    if (!basesComVaga) {
        return true; 
    }

    // 3. Se a string devolvida pelo Script Include (sys_idIN...) NÃO contiver o ID da Base atual, ela lotou!
    if (basesComVaga.indexOf(baseId) === -1) {
        // Exibe a mensagem de erro vermelha no topo da tela
        g_form.addErrorMessage('Operação cancelada: Não é possível adicionar o inscrito. Esta base já atingiu o limite máximo de lotação.');

        // Retorna false para IMPEDIR a inserção no banco de dados e cancelar o Submit
        return false; 
    }

    // Se passou por tudo, a base tem vaga, então permite salvar e seguir para o Flow!
    return true; 
}
